/* Cohesive Session 2 lessons. Provenance and unresolved source differences live in the audit ledger. */
function integrateSession2(){
  const p=(text)=>`<p>${text}</p>`;
  const steps=(items)=>`<ol class="s2-steps">${items.map(([title,text])=>`<li><strong>${title}</strong><p>${text}</p></li>`).join('')}</ol>`;
  const bodies={
    training:
      section('建园地点与材料',
        p('葡萄园管理以合理成本获得符合目标风格的健康、成熟葡萄。建园需兼顾环境、市场与作业条件，再确定材料、密度、骨架和冠层。')+
        table(['评估什么','怎样影响选择'],[
          ['平均温度、降雨、日照','判断品种能否成熟、是否需要灌溉，以及霜冻、晒伤和潮湿病害的主要风险。'],
          ['土壤肥力、保水与排水','影响根区水分、养分和植株长势。坡地降雨可能形成径流，降雨不少仍可能根区缺水。砧木与土壤不匹配还可能引发黄化。'],
          ['品种与砧木','品种需适合气候、目标风格和市场；选择也受种植传统及部分产区的法定品种限制影响。砧木需与土壤和病虫害风险相匹配。'],
          ['基础设施与资源','电力、水源的距离、可用劳动力、拖拉机与采收机的可获得性，以及土地成本，都会改变建园与运营成本。']
        ])+
        p('种苗可经扦插、品系选择取得，再嫁接到适宜的抗性砧木；接口可用蜡保护，经温室或苗圃培育后定植。部分自根老藤是例外，适用性仍取决于地点和根瘤蚜等风险。'))+
      section('种植、投产与更新',
        steps([
          ['准备土地','清理原植被、检测土壤，按需要补充不足养分。品种、砧木和园地设计应在栽种前确定。'],
          ['种植与保护','嫁接苗可人工或机械种植。套管减少动物伤害，支柱与铁丝支撑，滴灌管供水，澳大利亚新园可同时见到这些设施。'],
          ['建立植株与产出','幼藤需要适量供水；某些限制灌溉的地区对建园幼苗设有例外，需按当地规定判断。通常栽种第三年开始有收成。'],
          ['分批更新','多数葡萄藤约30–50年更新，也可活得更久。老藤可产浓郁果实，但常减产、多病，需权衡品质与利润。拔除后可按园地情况休耕3年或更长以恢复土地；分批重植可减少同时停产面积。']
        ])+
        courseFigure('environment','新园设施：透明套管保护幼苗，支柱与铁丝支撑植株，黑色滴灌管供水。','new-vines'))+
      section('密度、整枝、修剪与搭架',
        table(['术语','管理对象','联系到成熟与作业'],[
          ['种植密度 Planting density','单位面积的株数，以及株距、行距','决定植株竞争、单株空间和机械通行条件。'],
          ['整枝／整形 Training','主干与主蔓等多年生木的形状','建立永久骨架，安排结果部位及后续冠层。'],
          ['修剪 Pruning','去除不需要的叶片、新梢或木质枝条','冬剪主要决定一年生木上保留芽的数量与位置；夏剪调整绿色部分。'],
          ['搭架 Trellising','支柱、铁丝等支撑系统','安排枝条与新梢，影响光照、通风、喷洒和机械作业。']
        ])+
        p('四者共同影响光合作用、果实成熟、植株平衡、健康和成本。密度、每株留芽数与每公顷产量，是三个需要联系起来分析的量。'))+
      section('种植密度与资源竞争',
        p('种植密度以株／公顷表示，常见1000–10000株／公顷。1公顷为100×100米，1英亩约0.4公顷。密度需结合土壤保水排水、降雨、灌溉、肥力、品种、长势、冬剪留芽、株行距及机械通行确定。')+
        table(['资源情境','可采用的方向','原因与条件'],[
          ['水分非常有限','较低密度','减少植株间争水，让每株利用更大土壤范围；坡面径流也可能造成根区供水不足。'],
          ['肥力低，但雨水充足','较高密度，配合适合的单株留芽量','即使肥力偏低，水足也可能带来旺盛枝叶。竞争可限制单株长势、减轻遮阴与通风不足。芽太少时每芽分得储备多，容易徒长；芽太多时资源不足，成熟受阻。'],
          ['养分和水分都丰富、长势极旺','较低密度与大树型、多主蔓或较多长枝配合','单靠增加密度可能仍压不住旺长；给单株较大的骨架与冠层空间，分配生长势，兼顾产量和质量。']
        ])+
        p('欧洲部分园地接近每公顷一万株并控制单株芽数；新西兰部分肥沃、多雨园地采用大树型。密度须与资源和系统配合，不能按地区统一指定。'))+
      section('头状、主蔓与大树型',
        table(['整枝方式','多年生木的形态','管理联系'],[
          ['头状 Head training','永久木较少，主要是直立主干；顶端可有几根短干臂','可以配合短枝或替换长枝修剪，也可以搭架。水平绑缚的一年生结果长枝仍可每年替换。'],
          ['主蔓 Cordon training','主干上有一根或多根水平延伸的多年生木臂','常见单主蔓或双主蔓，通常配合短枝修剪。永久木建立较慢，稳固而规则的结构有利于机械管理。'],
          ['大树型 Big vines','两个以上主蔓，部分可有4根或更多；单株占地较大','可用于肥沃、多雨且长势旺盛的园地，需要更大的株间空间。']
        ])+
        p('识别依据是木龄与永久骨架：头部有无长期保留的水平木臂，而非一年生长枝的方向。'))+
      section('高干与矮干：根据地面影响取舍',
        p('头状和主蔓整枝都可以做成高干或矮干。低位结果部位可利用地表蓄热；容易发生春季近地面霜冻时，提高结果部位可远离最冷的近地空气，降低嫩芽暴露风险。')+
        p('高度取决于气候、地表、品种热量需求、树形及作业方式，不可按欧洲园地或品种统一规定。')+
        flow('地点与品种','资源和主要风险','密度、骨架与高度','成熟、作业和成本')),

    pruning:
      section('木龄、芽与结果新梢',
        table(['结构','怎样形成','与结果及冬剪的联系'],[
          ['当年新梢 Shoot','生长季从芽长出的绿色枝条，带叶片、花序和果串','果实生长在当年的结果新梢上；叶片为生长与成熟制造糖分。'],
          ['一年生木 Cane','上一生长季的新梢在冬季木质化，到次年春季成为一年生木','其芽可在下一季长出新梢；冬剪决定保留多少芽、留在哪里。'],
          ['多年生木 Permanent wood','超过一年的主干、主蔓等长期骨架','承担支撑和输导。老木的潜伏芽也可能萌发新梢，常规结果管理主要围绕一年生木上的结果芽展开。']
        ])+
        p('水平枝的方向本身不能确定木龄。每年更新的水平结果长枝仍是一年生木；长久保留的水平木臂才是主蔓。'))+
      section('年周期与季节作业',
        p('典型月份随地点、品种、年份而变；南北半球相差约半年。')+
        table(['阶段与示例月份','植株发生什么','管理重点'],[
          ['冬季休眠｜北12月至次年3月／南6–9月','新梢逐渐木质化，根部储存碳水化合物，供下一季开始生长；极冷可伤芽甚至杀藤','处理死亡木、冬剪与绑缚；需要时培土保护植株。'],
          ['萌芽｜北3–4月／南9–10月','芽膨大展开成为新梢；日均温超过约10°C是常用提示，品种的具体需求不同','留意春霜。Chardonnay、Pinot Noir较早萌芽，Cabernet Sauvignon较晚，暴露风险不同；开始关注虫害和真菌病。'],
          ['生枝长叶｜北3–5月／南9–11月','开花前新梢迅速生长；初期依靠越冬碳水储备，叶片成熟后转由光合作用供能','早期需要充足水分和养分；搭架园绑缚新梢，减少风损。'],
          ['开花坐果｜北5–6月／南11–12月','温暖、足光、少雨或无雨有利受精坐果，并非每朵花都会结果','寒冷阴雨可加重落花 coulure（坐果失败超过正常）及小粒果／部分僵化 millerandage（出现小而无籽果粒），降低产量。'],
          ['转色成熟｜北7–9月／南1–3月','坐果后约6–8周果粒仍绿且硬；转色后红葡萄渐红紫，白葡萄渐透明、金黄。果粒增大多汁，糖升酸降，风味和单宁发生变化','按需要修整冠层、保持通风受光；轻度水分限制可抑制徒长。转色后可摘青调节负载，但并非所有生产者都采用。'],
          ['采收｜北9–10月／南3–4月','在目标糖、酸、风味与健康达到平衡时收获','干燥天气更理想；临收降雨会稀释并增加腐烂。接近采收需按规定提前停用相关药剂，遵守安全间隔以免有害残留。']
        ])+
        p('各阶段均需监测，按风险、许可及安全间隔用药，不必固定喷洒。')+
        courseFigure('cycle','左：落叶休眠期的木质骨架，可安排冬剪。右：芽已展开，此时重点转向防春霜及后续新梢管理。','winter-bud')+
        p('<a href="#lesson/cycle">葡萄藤的结构与生理 →</a>'))+
      section('冬剪与夏剪',
        table(['操作','对象与时机','目的'],[
          ['冬季修剪 Winter pruning','休眠期的木质枝条，主要是一年生木','确定保留芽的数量和位置，安排下一季新梢分布及潜在产量；芽不要挤在一起，以利后续冠层管理。'],
          ['夏季修剪 Summer pruning','当年新梢和叶片','修整过长冠层、去除多余新梢、适量摘叶，调整遮阴、空气流动、果区暴露及喷药可达性，控制多余生长，使糖更有效用于果实成熟。']
        ])+
        p('冬剪处理的是带芽枝条，并不等于剪除永久主干或主蔓。留芽多会增加潜在新梢与果串，但实际产量还取决于芽的结果力、萌芽率、坐果、天气与病虫害。夏剪则须保留足够健康叶片；炎热强光条件下，果实还需要必要遮阴。'))+
      section('短枝修剪与年度更新',
        steps([
          ['选择一年生枝并剪短','每个短枝 spur 通常保留2–3个芽，让它们成为下一季新梢的出发点。'],
          ['保留永久骨架','短枝可分布在头状整枝顶部，也可规则排列在多年生主蔓上。'],
          ['进入下一轮更新','芽萌发成新梢，长叶、开花结果；新梢木质化后，下一次冬剪再次选择和更新。']
        ])+
        p('规则分布的短枝可降低部分技术投入、便于机械预剪，但机械化仍取决于整枝与搭架。不搭架灌木型难以采用常规行列机器作业。')+
        courseFigure('management','头状短枝：结果短枝围绕主干顶部，未形成水平永久主蔓。本图用于辨认骨架，实际留芽以正文的2–3芽为准。','head-spur'))+
      section('替换长枝修剪',
        steps([
          ['移除已完成结果任务的长枝','上一季结果长枝不再继续保留为永久水平木臂。'],
          ['选择成熟的一年生枝','通常保留1–2条，每条约8–20个芽。单居由式 single Guyot 留一条，双居由式 double Guyot 留两条。具体设计可调整芽数，例如一种单居由操作保留约8芽。'],
          ['绑到水平铁丝上','让芽和下一季新梢分布合理，同时可保留一条短更新枝，为下一年提供候选结果长枝。'],
          ['逐年替换','新一年选出的枝条取代用过的结果枝，永久主干继续保留。']
        ])+
        p('长枝选择、修剪与绑缚需熟练人工，比规则化机械预剪耗工，但不妨碍后续机械采收。基部芽结果力低的品种或园地可能更适合长枝修剪；结果力低不等于不能萌芽。')+
        courseFigure('management','头状替换长枝：左右绑在铁丝上的浅褐色枝条是一年生结果长枝，下一轮冬剪需更新；不是永久主蔓。','head-cane')+
        callout('总留芽量与结果力','少数长枝与许多短枝可有相近总留芽量。产量还取决于芽的结果力与植株负载能力，不能仅按长、短枝判断。'))+
      section('整枝 × 修剪的四种组合',
        table(['永久骨架 × 冬剪','例子','识别关键'],[
          ['头状 × 替换长枝','Guyot · 居由式','没有长久保留的水平主蔓；一年生结果长枝水平绑缚并逐年替换。'],
          ['主蔓 × 长枝','Sylvoz','永久主蔓上保留长枝，长枝的存在不改变其主蔓骨架。'],
          ['头状 × 短枝','Bush／Gobelet · 灌木／杯形','头部保留短枝，常见不搭架形式，新梢自然展开或下垂。'],
          ['主蔓 × 短枝','Midwire cordon','永久水平木臂上分布短枝，新梢可向上定位。']
        ])+
        courseFigure('management','主蔓短枝：深色水平木臂是多年生主蔓，上方较浅的短枝是冬剪保留的一年生木；骨架与每年更新的结果木要分开。','cordon-spur')+
        p('头状长枝、主蔓短枝均可配合VSP；依次辨认永久木、一年生枝与当年新梢。冬剪后的木质骨架与夏季绿色冠层属于不同生长阶段，不能当作同一时刻比较。')),

    canopy:
      section('冠层管理的目标',
        p('冠层／叶幕涵盖所有绿色部分，主要由当年新梢与叶片组成；可通过新梢定位、搭架、修梢、疏梢、摘叶及保留遮阴调整结构。')+
        p('管理需平衡光合作用、成熟、通风防病与防晒。凉爽、潮湿或少光处需改善受光通风；炎热强光处需保护果实。')+
        table(['操作','希望解决的问题','操作过度的风险'],[
          ['去除多余新梢、修整过长冠层','减少拥挤、互相遮阴和湿气滞留','损失有效叶面积，或刺激再生长。'],
          ['果区适量摘叶','增加受光和空气流动，使喷洒更容易覆盖目标','果实过度暴露、晒伤或过热。'],
          ['保留部分叶片、让顶梢下垂','在强光炎热环境中给果实遮阴','遮阴过重妨碍成熟，并可能增加潮湿和腐烂。']
        ])+
        callout('叶片既遮阴，也制造糖分','摘叶须保留足够健康叶片，并结合气候、方位、时机与果实暴露程度决定强度。'))+
      section('不搭架的灌木形',
        p('灌木形常配合头状整枝、短枝修剪，新梢自然展开或下垂。低矮紧凑可在部分风大地点保持稳定，并给果实遮阴；省去完整支柱、铁丝系统可降低建园和部分绑缚成本。')+
        p('干燥、光照强的温暖或炎热地点常能利用这些特点，例如 Southern Rhône、Barossa Valley，以及西班牙和澳大利亚部分园地。多云、阴凉或潮湿时，拥挤的叶幕则可能妨碍成熟、滞留湿气并增加霉菌风险。在 Beaujolais，部分这类新梢的顶端会绑在一起，以改善果串受光和通风。')+
        p('不搭架灌木形的冠层位置较难控制，通常不适合常规机械采收；须按风况、结构、成熟需求及劳动力判断，不能只看地区名称。'))+
      section('搭架的三个目的',
        p('搭架使用支柱和铁丝支撑、安排长枝与新梢。头状和主蔓骨架都可以搭架，短枝和替换长枝修剪也都能与适当的架式组合。')+
        table(['目的','产生的影响'],[
          ['调节光照','使冠层的受光和果实暴露适应当地气候，支持光合作用与成熟。'],
          ['改善通风与干燥','减少密闭叶幕里的湿气和病害条件，并使需要的喷洒覆盖更有效。'],
          ['便利机械作业','在适当行距、地形与树形下，为机械采收等作业创造通行和操作条件。']
        ])+
        p('开放冠层可降低部分病害风险与成本，仍需监测、防护；不能替代根系害虫或鸟害等针对性措施。'))+
      section('VSP与调整型VSP',
        p('<strong>VSP · Vertical Shoot Positioning，新梢垂直定位／垂直分布</strong>，把新梢向上排列并以铁丝固定，形成较窄、留有空隙的冠层。这有利于受光、空气流动和管理可达性，可配合头状或主蔓整枝，以及短枝或长枝修剪。')+
        p('凉爽、潮湿、少光园地可受益于开放VSP。炎热强光处可采用调整型VSP：部分顶梢不绑缚、自然下垂，为果实遮阴，同时保留机械采收的可能。')+
        courseFigure('management','左：新梢向上定位，冠层较开放。右：部分顶梢弯垂，为果区遮阴。比较的是夏季新梢安排，不是头状与主蔓骨架。','vsp-compare')+
        flow('判断光、热与湿度','安排新梢和果区暴露','保留健康叶片与通风','平衡成熟、防病和防晒'))+
      section('建园、管理与采收成本',
        table(['阶段','搭架系统','不搭架灌木系统'],[
          ['建园投入','支柱、铁丝和安装增加材料及施工成本','省去部分材料和安装投入。'],
          ['生长季管理','绑梢、定位和修整需要人工','可减少部分绑缚，但冠层仍需管理。'],
          ['采收','地形、株行距与树形合适时，可机械化提高速度','常规机械采收较难，通常需要人工。']
        ])+
        p('总成本需合计建园、修剪、绑梢与采收，并考虑当地工价、购／租机成本及作业规模。')),

    balance:
      section('产量、资源与成熟能力',
        p('产量需兼顾品质目标与经营可行性。光、热、水或养分受限时，过大负载妨碍成熟，因此欧洲部分资源有限园地选择低产。')+
        p('资源充足、冠层健康时，较高产量也可优质。负载过低未必改善品质，反可能增加枝叶遮阴，并减少可售酒量、提高单位成本。')+
        table(['情境','需要判断什么'],[
          ['资源有限、果实负载过大','成熟不足、风味不充分的风险，是否需要减负载。'],
          ['资源充足、冠层健康、负载合适','能否在较高产量下仍达到目标成熟度与品质。'],
          ['资源丰富、枝叶旺盛而拥挤','如何安排骨架和冠层、分配生长势；无限施肥或放任生长都会破坏平衡。'],
          ['产量降得很低','减少的果串是否真的改善成熟，还是只增加成本。']
        ]))+
      section('产量的单位、预测与经营限制',
        p('产量可用葡萄重量表示，如<strong>吨／公顷</strong>，也可用酒的体积表示，如<strong>百升／公顷</strong>。密度描述每公顷有多少株，留芽量描述潜在结果点，产量则是最后获得的葡萄或酒。')+
        p('产量预测需匹配合同、酒厂接收能力、容器、作业计划及产区限制。冬剪留芽仅是起点，霜冻、萌芽、坐果与病虫害仍会改变产量。')+
        p('风格、品质等级、价位和经营目标共同决定负载。资源有限时，提高成熟度或浓缩度可能需减产；其他风格未必相同。香槟、波尔多等产区可有产量规定，需核对适用条款与年份。')+
        flow('资源、品种与冠层','目标风格和成熟度','法规、合同与酒厂容量','可实现的产量与成本'))+
      section('冬剪与摘青',
        table(['方法','时机与对象','影响与限制'],[
          ['冬季修剪','萌芽前决定带芽枝条的保留数量和位置','调整潜在结果负载及分布，之后还要观察天气和坐果结果。'],
          ['摘青 Green harvesting','生长季去掉部分尚未成熟的果串，常在转色后进行','减少剩余果实间竞争，但应结合品种、年份、成熟目标、成本和预计收益。']
        ])+
        p('摘青过早可引起补偿性生长，如剩余果粒增大，抵消减串效果甚至稀释风味；过晚则难改善成熟，先前投入也已发生。时机须按具体条件确定。')+
        callout('摘青与摘心要分开','摘青疏除青葡萄串，直接调节果实负载；摘心处理新梢尖端，属于绿色冠层操作。两者对象与目的不同。'))+
      section('情境一：炎热干燥、灌溉有限',
        p('条件：<strong>内陆、炎热、强光、少雨，灌溉水没有或极有限，土壤保水良好</strong>；暂不考虑法规，主要限制是水。')+
        table(['条件','选择','为什么'],[
          ['水分有限','低密度种植','减少争水，让每株有足够根区取得土壤储水。'],
          ['强光、高温','灌木形，或允许搭架植株顶梢下垂','以叶片遮阴，降低果实过热及晒伤风险。'],
          ['少雨、较干燥','在保证基本通风下保留适当遮阴','潮湿真菌病的压力相对较低，冠层取舍更偏向防晒。']
        ])+
        p('西班牙部分低密度灌木园：株间距大、植株低矮独立、没有连续铁丝架；适用前提包括保水土壤与有限灌溉。')+
        courseFigure('cases','观察低矮独立的灌木、较大株间距，以及遮护果串的叶片；它们回应本题少水、强光的限制。土壤保水与灌溉条件来自题设，不能单凭图判断。','dry-bush'))+
      section('情境二：温和多雨、土壤贫瘠',
        p('条件：<strong>近海、温和、全年雨多、土壤贫瘠</strong>；暂不考虑法规。雨水充足仍可支持旺长，贫瘠不等于长势弱。')+
        table(['条件','选择','为什么'],[
          ['雨水充足，需约束单株生长','高密度，配合适量留芽','增加植株竞争、分配生长势，减少过旺枝叶。'],
          ['多雨、真菌病风险','开放、通风的VSP冠层','促进空气流通与干燥，降低湿气滞留。'],
          ['多云，光照受限','合理定位新梢、提高有效受光','帮助叶片工作和果实成熟。']
        ])+
        p('波尔多案例采用高密度、头状整枝、替换长枝与VSP。两种情境的选择取决于资源和风险，不能仅凭近海或内陆定方案。')+
        courseFigure('cases','观察连续铁丝架、向上排列的新梢与较窄的开放冠层；重点是受光和通风。高密度、贫瘠土壤及全年多雨来自本题条件，不由海景或绿色地表推断。','wet-vsp')),

    health:
      section('各生长阶段的天气风险',
        table(['阶段','主要风险','可能影响'],[
          ['春季','霜冻、干旱、冰雹、雨、风','嫩芽、新梢受伤，开花坐果可能受干扰。'],
          ['夏季','干旱、冰雹、雨、晒伤','叶片功能、供水、果实健康和成熟受影响。'],
          ['秋季','雨、冰雹、风','损伤或稀释果实，增加腐烂，压缩采收窗口。'],
          ['冬季','冬季冰冻','芽、多年生木或整株受伤，严重时需更新植株。']
        ])+
        p('灾害损失取决于发生阶段、强度与植株状态。<a href="#lesson/climate">气候与天气机制 →</a>'))+
      section('根、叶与果实的受害路径',
        p('叶损减少光合作用、阻碍成熟；果实被取食或感染直接减产、降质；根损妨碍水与养分吸收，严重病虫害可致整株死亡。即使果粒仅被咬伤，伤口也可增加真菌感染。')+
        table(['对象','受害路径','针对性管理'],[
          ['根瘤蚜 Phylloxera','侵袭根系，影响生长与存活','选择适合园地的抗性砧木并嫁接；完整机制见 <a href="#lesson/roots">Session 1 · 砧木与根系</a>。'],
          ['线虫 Nematodes','很小的土壤蠕虫，侵袭根系、影响水与养分吸收；部分传播病毒','重视预防、健康种苗、抗性砧木和针对实际问题的重植前土壤处理。冠层VSP不能解决根区线虫。'],
          ['鸟类 Birds','啄食、啄破果粒，增加腐烂入口','转色、成熟或采收临近时使用防鸟网，考虑材料和铺设劳动成本；新西兰园地有网覆盖果区的例子。'],
          ['哺乳动物 Mammals','取食果实或损坏植株，包括兔、鹿、野猪、袋鼠','围栏等物理屏障，按具体对象布置。'],
          ['昆虫与螨类','取食叶片或果实，某些还传播病原；叶螨也是害虫对象之一','先辨认对象，再用相应杀虫管理或综合虫害管理方案。']
        ])+
        p('防鸟网、围栏、砧木、冠层与药剂各有对象，需按威胁及受害路径选择。'))+
      section('霜霉病、白粉病与灰腐',
        table(['病害','有利条件与表现','后果'],[
          ['霜霉病 Downy mildew','温暖潮湿，侵袭绿色部分；叶片出现黄斑、叶背灰白绒状生长','严重时早落叶；花序和幼果也会受害，造成减产。常与真菌病害一起讨论，但病原属卵菌。'],
          ['白粉病 Powdery mildew','温暖、阴暗且有一定湿度时有利；绿色部分出现灰白粉层','叶片可干枯早落；果粒可萎缩、开裂，或成熟异常。'],
          ['灰腐 Grey rot · Botrytis cinerea','潮湿有利于感染果实','破坏风味，并可使红葡萄酒颜色变浅。某些成熟白葡萄在合适天气中可形成有益贵腐，见 <a href="#session2/harvest">采收与贵腐</a>。']
        ])+
        p('白粉病可用硫制剂，霜霉病可用含铜波尔多液，也有其他针对性药剂。多雨常需更频繁防护，须遵守许可、安全间隔与采前停药要求；防治不能保证受损组织恢复。')+
        p('开放冠层促进通风、干燥，减少湿气滞留及病害条件，可减少用药和成本、改善喷洒覆盖；仍须持续监测。'))+
      section('病毒与细菌性病害',
        table(['类别','例子与影响','管理逻辑'],[
          ['病毒','病毒病常不立即致死，却持续限制正常功能、降低产量与品质；卷叶病是例子，可表现为叶片卷曲、变色','可经感染的繁殖材料或特定媒介传播，某些由线虫传播。使用健康材料、控制媒介，必要时移除病株并处理地块；普通杀菌喷雾不能治愈病毒。'],
          ['细菌性病害','例如皮尔斯病 Pierce’s disease；可减产降质，严重者死亡','关注检疫、叶蝉等传播媒介及其生命周期，必要时移除感染植株，并针对具体病原处理地块。']
        ])+
        p('移除病株、处理土壤及控制媒介须针对病害和传播路径；没有适用于所有病原的根除方案。'))+
      section('常规、可持续、有机与生物动力',
        p('20世纪后半叶农药、化肥的例行使用增多，其环境影响促使生产者、消费者及立法者寻求可持续、有机、生物动力等替代取向。')+
        table(['方式','主要做法','限制与条件'],[
          ['常规 Conventional','在适用规定下使用化肥、杀虫剂、杀菌剂、除草剂等投入','有时称“传统”，不等于马耕或古老农业；投入仍受规则约束。'],
          ['可持续 Sustainable','监测害虫生命周期、天气预报与湿度，在有效时机有针对性操作，减少不必要的例行喷洒','仍可按需要使用化学投入。综合虫害管理可引入天敌；多样植物提供栖息地、吸收二氧化碳，翻入土中可补充养分。'],
          ['有机 Organic','与可持续有重叠，限制许多合成肥料和农药，按标准使用允许的投入','允许种类、剂量依认证标准而异；认证须机构认可，并有有机经营转换期。天然物质也未必获准。'],
          ['生物动力 Biodynamic','以有机做法为基础，采用特定制剂、农场整体观和相关操作日历，也有认证机构','与Rudolf Steiner、Maria Thun有关；把土壤、地球、大气和天体视为关联整体，按天体周期及花／果／根／叶日安排操作。这些理念不意味着其全部因果主张都已获科学证实。']
        ]))+
      section('栽培方式、成本与品质',
        p('有机、生物动力不保证优质，常规也可产优质葡萄。限制投入可增加除草、人工、监测及风险管理需求，如机械除草、翻耕或人工处理。')+
        p('劳动和损失风险可推高成本与价格，但不直接证明果实更好。环境表现也须按具体措施与指标评价，认证不代表各项最优。')),

    harvest:
      section('采收时间与目标成熟度',
        p('转色以后，糖分增加、酸度下降、风味发展，单宁通常变得不那么苦涩。糖分常用于追踪成熟并估计潜在酒精度，还要同时判断酸、风味、单宁等酚类成熟，以及果实健康。')+
        table(['判断因素','怎样改变决定'],[
          ['品种、气候与地点','早熟和晚熟品种窗口不同，理想成熟平衡也不同。没有适合所有酒款的统一糖、酸或日历数值。'],
          ['目标风格与品质','清爽、较低酒精度和浓郁饱满的目标，可能要求不同采摘成熟度。'],
          ['当年天气与健康','冰雹或大雨预报可能迫使提前，避免损伤、膨果稀释和腐烂。气候常态与当年预报须分别判断。'],
          ['法规与作业能力','协调人员、设备、采摘、运输及酒厂处理时间，避免集中到货超出接收能力、无法及时加工。']
        ])+
        p('种植者与酿酒师共同决定，分区取样、分析糖酸并尝果。变暖可使成熟、采收前移，仍应依据当年实测；早、中、晚均相对当地窗口及目标成熟度。'))+
      section('早采、正常采与晚采',
        table(['选择','可取得的效果','需要防范'],[
          ['早采','保留酸度和新鲜感；较低糖分带来较低潜在酒精度','过早可有青生、风味不足；红葡萄还要注意单宁成熟。'],
          ['正常采收','在目标风格下平衡糖、酸、风味、单宁与健康','不同品种、地点及风格的正常成熟点并不相同。'],
          ['晚采','更成熟、浓郁，甚至干果风味；潜在酒精度可更高、酒体更丰满','酸流失、失去新鲜感、过高酒精，以及天气和病害风险。']
        ])+
        p('晚采原料充分发酵也可酿干型酒，甜度还取决于原料与发酵等决定。藤上脱水不同于采后风干。')+
        table(['风格例子','应理解的关系'],[
          ['Hunter Valley Sémillon · 猎人谷赛美蓉','较早采收可塑造高酸、清爽、较低酒精度的干型风格，例如约10–11%的酒款；具体度数因酒款而异。'],
          ['意大利部分Pinot Grigio · 灰皮诺；Vinho Verde · 葡萄牙绿酒','较早采摘可与简单、易饮、清爽的目标相联系，仍须按具体酒款判断。'],
          ['Beaujolais Nouveau · 博若莱新酒','新酒上市早，是上市与酿造安排的特征，不能单独用来证明风格由提前采收造成。'],
          ['Amarone · 阿玛罗尼','采用采后室内风干，浓缩或干果味不能直接证明它属于晚采。'],
          ['德国特定晚采类别、阿尔萨斯晚采、Jurançon · 朱朗松、白诗南、Tokaj · 托卡伊','可用来比较晚采及不同甜酒风格；不能把整个地区、所有雷司令或所有白诗南概括为晚采。']
        ]))+
      section('贵腐条件、浓缩与选果',
        steps([
          ['成熟葡萄与交替天气','Botrytis cinerea 也会造成破坏性灰腐。适合的成熟葡萄，配合潮湿、多雾的早晨促进感染，再有温暖晴朗、干燥的下午帮助失水、限制破坏性腐烂，才可能发展出有益贵腐。'],
          ['失水与成分变化','真菌改变果皮通透性，水分散失使糖和某些风味成分浓缩，并形成贵腐相关风味。失水也可浓缩酸，但感染过程会消耗或改变部分成分，最终酸度不能一概断定上升。'],
          ['选择适采果粒','感染及发展程度在不同串、甚至同串果粒间都不一致，需熟练工人逐粒或局部挑选，并反复进园。'],
          ['解释成本和风险','可能需要五次或更多次进园。逐粒选果、较长采收窗口、失水后出汁量低及天气失败风险，共同提高成本。']
        ])+
        p('“腐而不烂”并非果皮不变。持续潮湿可导致灰腐，管理与开放冠层不能代替适宜天气；贵腐时段随产区、年份而变。')+
        p('例子有 Sauternes · 苏代、德国BA／TBA、Tokaji Aszú、阿尔萨斯贵腐酒类别及澳大利亚Riverina。比较时须区分原料成熟与糖度、感染程度、选果和类别要求。')+
        callout('贵腐酒的要求各不相同','须分别核对逐粒感染、采收糖度、浓缩原料许可和酒庄选果。TBA、Tokaji Aszú、苏代及d’Yquem的法规、风干原料许可与酒庄比例不能互相套用。'))+
      section('机械采收的条件与取舍',
        p('常规采收机跨行振落并接住果粒，果梗通常留藤，经输送和部分分离系统送往拖车。法国园地有此类实例，收集对象主要是果粒。')+
        table(['方面','优势与适用条件','限制或后续要求'],[
          ['速度与采收窗口','可在坏天气前抢收，或在品种迅速过熟前完成，例如长相思。某些作业中速度可达人工十几倍，实际差距依机器与园地条件而变','需协调运输和酒厂接收能力，以免快采后无法快处理。'],
          ['温度与能耗','可以凉夜采收，降低后续冷却成本与能耗，减慢氧化、降低过早发酵风险','破损果粒仍需迅速运输和处理，并控制温度、微生物与氧化。'],
          ['地形与系统','适合平地或缓坡、可通行的行距和适宜树形，以及易脱梗而不易损伤的果实','陡坡、某些密植或不搭架灌木系统不便常规机器进入。'],
          ['选择性与完整性','部分机器有分选功能，酒厂还可再次分选','传统选择性有限，可混入未熟、不健康或破损果，以及叶、昆虫等MOG（matter other than grapes，非葡萄果实物质）；无法提供需要的完整果串。'],
          ['成本','规模适合时可降低部分采收人工','购机投入高，实际成本需比较租用、规模、当地工资和设备使用率。']
        ])+
        courseFigure('management','跨行采收机从葡萄行上方通过，右上输送带把收集的果粒送入容器。它收获果粒，不能提供完整果串。','machine'))+
      section('人工采收、整串与陡坡',
        p('人工用剪刀剪串，可在园内选果，留下未熟或腐烂果，并多次进园细选发展不均的贵腐果。速度慢、需工多，缺工时尤其贵；部分地点与机械成本差别不大，须按当地核算。')+
        p('仔细人工采收较少伤果，小而浅、可叠放的容器进一步减压，仍需及时、适温运输。完整果串保留果梗，可用于整串压榨取得清洁果汁，或红酒整串发酵，如Beaujolais和Champagne的部分酿造情境；并非所有酒款都需整串。')+
        p('Douro、Mosel、Northern Rhône的陡坡难用常规采收机，平坦地块须另作判断。阿根廷也有人工采收实例。')+
        courseFigure('management','人工剪下果串，轻放小筐等浅容器以减少挤压。白色网用于防鸟，是另一项防护措施；人工采收并不要求铺网。','manual')+
        callout('采收方法与品质分别判断','两种方式都可以生产优质酒，人工也可用于普通酒，机械采后仍可分选。高品质来自适合的成熟度、健康果实和及时处理；清爽风格需要快速低温处理，并不说明人工采收本身必然带来氧化。'))+
      section('全年管理与采收衔接',
        p('品种、品系、抗性砧木与土壤适配，建园供水与支撑、冬剪留芽与绑缚、受光及冠层管理、病害监测共同决定成熟能力。天气站与观察可减少不必要喷药；成熟期分区取样，采后迅速运输、处理。')+
        flow('环境、材料与园地设计','冬剪和冠层平衡','风险监测与成熟取样','采摘、运输、酒厂处理')+
        p('操作须对应条件，并评估对成熟、健康、风险与成本的影响。'))
  };
  s2Units.forEach(unit=>{if(bodies[unit.id]) unit.body=bodies[unit.id];});
}
